/* Global app styling for the desktop and mobile shells. */
@import "tailwindcss";
@import "tw-animate-css";
@import "shadcn/tailwind.css";

@custom-variant dark (&:is(.dark *));

:root {
  /* DESIGN ATOMS — edit these values to retheme the desktop UI. */
  --design-font: "Helvetica Neue", Helvetica, Arial, sans-serif;
  --design-light-bg: #fafafa;
  --design-light-text: #292421;
  --design-light-muted: rgba(41, 36, 33, 0.62);
  --design-light-border: rgba(41, 36, 33, 0.1);
  --design-light-selection: rgba(41, 36, 33, 0.065);
  --design-dark-bg: #0b0a09;
  --design-dark-text: oklch(82% 0.006 67.8);
  --design-dark-muted: oklch(57% 0.008 67.8);
  --design-dark-border: rgba(255, 255, 255, 0.1);
  --design-dark-selection: rgba(255, 255, 255, 0.075);

  font-family: "Avenir Next", "SF Pro Text", "Segoe UI", "Noto Sans", Arial, sans-serif;
  font-size: 14px;
  line-height: 1.35;
  color: #101418;
  background-color: #ffffff;
  --titlebar-height: 40px;
  --left-panels-drag-height: 28px;
  --ui-bg: #ffffff;
  --ui-pane: #ffffff;
  --ui-border: #d3d9df;
  --ui-border-strong: #9ba6b1;
  --ui-text: #101418;
  --ui-muted: #66717c;
  --ui-select: #f2f5f7;
  --ui-accent: #1f6feb;
  --radius: 0.625rem;
  --background: oklch(1 0 0);
  --foreground: oklch(0.141 0.005 285.823);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.141 0.005 285.823);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.141 0.005 285.823);
  --primary: oklch(0.21 0.006 285.885);
  --primary-foreground: oklch(0.985 0 0);
  --secondary: oklch(0.967 0.001 286.375);
  --secondary-foreground: oklch(0.21 0.006 285.885);
  --muted: oklch(0.967 0.001 286.375);
  --muted-foreground: oklch(0.552 0.016 285.938);
  --accent: oklch(0.967 0.001 286.375);
  --accent-foreground: oklch(0.21 0.006 285.885);
  --destructive: oklch(0.577 0.245 27.325);
  --border: oklch(0.92 0.004 286.32);
  --input: oklch(0.92 0.004 286.32);
  --ring: oklch(0.705 0.015 286.067);
  --chart-1: oklch(0.646 0.222 41.116);
  --chart-2: oklch(0.6 0.118 184.704);
  --chart-3: oklch(0.398 0.07 227.392);
  --chart-4: oklch(0.828 0.189 84.429);
  --chart-5: oklch(0.769 0.188 70.08);
  --sidebar: oklch(0.985 0 0);
  --sidebar-foreground: oklch(0.141 0.005 285.823);
  --sidebar-primary: oklch(0.21 0.006 285.885);
  --sidebar-primary-foreground: oklch(0.985 0 0);
  --sidebar-accent: oklch(0.967 0.001 286.375);
  --sidebar-accent-foreground: oklch(0.21 0.006 285.885);
  --sidebar-border: oklch(0.92 0.004 286.32);
  --sidebar-ring: oklch(0.705 0.015 286.067);
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  height: 100%;
}

body {
  margin: 0;
  background: transparent;
}

.window-shell {
  height: 100vh;
  overflow: hidden;
  background: transparent;
}

.app {
  position: relative;
  display: flex;
  height: 100vh;
  overflow: hidden;
}

.app-panels {
  flex: 1;
  width: 100%;
  height: 100%;
  min-height: 0;
  min-height: 100vh;
}

.app-panels [data-slot="resizable-panel"] {
  min-height: 0;
  min-height: 100vh;
}

.app-panels [data-panel] {
  height: 100%;
  min-height: 0;
  min-height: 100vh;
}

.app-single-pane {
  flex: 1;
  width: 100%;
  height: 100%;
  min-height: 0;
  min-height: 100vh;
}

.sidebar-toggle-btn {
  position: absolute;
  top: 5.5px;
  left: 82px;
  z-index: 32;
  width: 10px;
}

.tiptap-scroll::-webkit-scrollbar-thumb {
  min-height: 34px;
  border: 3px solid transparent;
  border-radius: 999px;
  background: color-mix(in srgb, var(--ui-muted) 45%, transparent);
  background-clip: padding-box;
}

.vim-mode-indicator {
  position: absolute;
  right: 14px;
  bottom: 10px;
  z-index: 2;
  border: 1px solid var(--ui-border);
  border-radius: 5px;
  padding: 3px 6px 2px;
  background: color-mix(in srgb, var(--ui-pane) 92%, transparent);
  color: var(--ui-muted);
  font-family: ui-monospace, "SFMono-Regular", Consolas, monospace;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  line-height: 1;
  pointer-events: none;
  user-select: none;
}

.vim-block-cursor {
  position: absolute;
  z-index: 3;
  box-sizing: border-box;
  border: 1.5px solid color-mix(in srgb, var(--ui-text) 88%, transparent);
  border-radius: 1px;
  background: color-mix(in srgb, var(--ui-text) 13%, transparent);
  pointer-events: none;
}

.tiptap-editor[data-vim-mode="visual"] .vim-block-cursor {
  border-color: color-mix(in srgb, var(--ui-accent) 92%, white 8%);
  background: color-mix(in srgb, var(--ui-accent) 34%, transparent);
}

.tiptap-editor[data-vim-mode="normal"] .tiptap-content,
.tiptap-editor[data-vim-mode="visual"] .tiptap-content {
  caret-color: transparent;
}

.tiptap-editor[data-vim-mode="insert"] .tiptap-content {
  caret-color: var(--ui-text);
}

.tiptap-editor[data-vim-mode="visual"] .tiptap-content::selection,
.tiptap-editor[data-vim-mode="visual"] .tiptap-content ::selection {
  background: color-mix(in srgb, var(--ui-accent) 34%, transparent);
}

.tiptap-editor[data-vim-mode="insert"] .vim-mode-indicator {
  border-color: color-mix(in srgb, var(--ui-accent) 45%, var(--ui-border));
  color: var(--ui-accent);
}

.tiptap-content {
  min-height: 100%;
  padding: 10px 12px 16px 22px;
  color: var(--ui-text);
  font-size: var(--editor-font-size, 14px);
  line-height: 1.6;
  outline: none;
}

.app.sidebar-collapsed .tiptap-content {
  padding-left: clamp(56px, 20vw, 380px);
