import { lazy, Suspense } from "react";
import { Menu } from "lucide-react";

import { NoteEditor } from "@/features/notes/editor/components/note-editor";
import { RecordingNoteHeader } from "@/features/recording/components/recording-note-header";
import { HandwritingNoteHeader } from "@/features/handwriting/components/handwriting-note-header";
import { SettingsDetailPane } from "@/features/settings/components/desktop/settings-panel";
import type { SettingsSectionId } from "@/features/settings/lib/sections";

import { focusNoScroll } from "@/shared/lib/dom";
import type { AppMode } from "@typenotes/shared/types";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/shared/ui/dropdown-menu";
import { useDesktopEditorPane } from "./hooks/use-desktop-editor-pane";

const MultiNoteLens = lazy(() =>
  import("@/features/lens/components/multi-note-lens").then((module) => ({
    default: module.MultiNoteLens,
  }))
);

type DesktopRightPaneProps = {
  appMode: AppMode;
  activeSettingsSection: SettingsSectionId;
  onOpenTrash: () => void;
};

export function DesktopRightPane({
  appMode,
  activeSettingsSection,
  onOpenTrash,
}: DesktopRightPaneProps) {
  const {
    activeNote,
    selectedNotePaths,
    activeNotePreview,
    editorMarkdown,
    handleEditorChange,
    flushSave,
    rightPaneRef,
    canOpenLens,
    shouldShowLens,
    lensNotes,
    isLensMenuOpen,
    setIsLensMenuOpen,
    openLens,
    closeLens,
    syncActiveNoteContent,
  } = useDesktopEditorPane();

  if (appMode === "notes") {
    return (
      <div className="pane editor-pane min-w-0">
        <div
          className="pane-body editor-body"
          ref={rightPaneRef}
          tabIndex={0}
          onClick={() => {
            if (shouldShowLens) {
              return;
            }
            const editorElement =
              rightPaneRef.current?.querySelector<HTMLElement>(
                ".tiptap-content[contenteditable='true']"
              ) || rightPaneRef.current;
            focusNoScroll(editorElement);
          }}
        >
          {shouldShowLens ? (
            <Suspense fallback={<div className="empty">Loading lens...</div>}>
              <MultiNoteLens
                notes={lensNotes}
                activeNote={activeNote}
                onBeforePersist={flushSave}
                onActiveNoteContentSync={syncActiveNoteContent}
                onExitLens={selectedNotePaths.length > 1 ? undefined : closeLens}
              />
            </Suspense>
          ) : (
            <div className="editor-single">
              <div className="editor-top-row">
                {canOpenLens ? (
                  <div className="editor-lens-menu-area">
                    <DropdownMenu open={isLensMenuOpen} onOpenChange={setIsLensMenuOpen}>
                      <DropdownMenuTrigger asChild>
                        <button
                          type="button"
                          className="editor-lens-menu-trigger"
                          aria-label="Open editor menu"
                        >
                          <Menu aria-hidden="true" />
                        </button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent align="end">
                        <DropdownMenuItem onClick={openLens}>
                          Open Lens
                        </DropdownMenuItem>
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </div>
                ) : null}
              </div>
              <RecordingNoteHeader notePath={activeNote} preview={activeNotePreview} />
              <HandwritingNoteHeader notePath={activeNote} preview={activeNotePreview} />
              <NoteEditor
                markdown={editorMarkdown}
                onChange={handleEditorChange}
              />
            </div>
          )}
        </div>
      </div>
    );
  }

  return (
    <SettingsDetailPane
      activeSection={activeSettingsSection}
      onOpenTrash={onOpenTrash}
      onPaneClick={() => focusNoScroll(rightPaneRef.current)}
    />
  );
}
import { useCallback, useEffect, useRef, useState } from "react";
import { deleteItems, readNote, renameItem, writeNote } from "@/features/notes/api/notes-api";
import { getAutoRenameTarget } from "@/features/notes/editor/lib/note-autoname";
import type { NoteFileNameFormat } from "@typenotes/shared/types";
import { getErrorMessage } from "@typenotes/shared/errors";

const emitTreeInvalidated = () => {
  window.dispatchEvent(new CustomEvent("notes-tree-invalidated"));
};

const emitNotePreviewsInvalidated = () => {
  window.dispatchEvent(new CustomEvent("note-previews-invalidated"));
};

export function useNoteEditor(
  activeNote: string | null,
  noteFileNameFormat: NoteFileNameFormat
) {
  const [noteContent, setNoteContent] = useState("");
  const [draftNoteContent, setDraftNoteContent] = useState("");
  const [noteDirty, setNoteDirty] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [saveError, setSaveError] = useState<string | null>(null);
  const saveTimer = useRef<number | null>(null);
  const noteContentRef = useRef(noteContent);
  const activeNoteRef = useRef(activeNote);
  const noteDirtyRef = useRef(noteDirty);

  useEffect(() => {
    noteContentRef.current = noteContent;
  }, [noteContent]);

  useEffect(() => {
    noteDirtyRef.current = noteDirty;
  }, [noteDirty]);

  const saveNow = useCallback(
    async (targetNote: string | null, content: string) => {
      if (!targetNote) {
        return;
      }
      setIsSaving(true);
      setSaveError(null);
      try {
        await writeNote(targetNote, content);
        // Preview refresh is intentionally asynchronous: typing and saving do
        // not wait for the navigation title to be recomputed.
        emitNotePreviewsInvalidated();
        if (activeNoteRef.current === targetNote && noteContentRef.current === content) {
          setNoteDirty(false);
          noteDirtyRef.current = false;
        }
      } catch (error) {
        const message = getErrorMessage(error);
        setSaveError(message);
        throw error;
      } finally {
        setIsSaving(false);
      }
    },
    []
  );

  // Load note content when activeNote changes
  useEffect(() => {
    let cancelled = false;
    const previousNote = activeNoteRef.current;
    const previousContent = noteContentRef.current;
    const previousDirty = noteDirtyRef.current;
    activeNoteRef.current = activeNote;

    const run = async () => {
      if (previousNote && previousNote !== activeNote) {
        try {
          const trimmed = previousContent.trim();
          if (previousDirty && !trimmed) {
            await deleteItems([previousNote]);
            emitTreeInvalidated();
          } else {
            if (previousDirty) {
              await saveNow(previousNote, previousContent);
            }
            if (trimmed) {
              // The editor owns the timing of the flush; the notes domain owns
              // the filename policy.
              const renameTarget = getAutoRenameTarget(
                previousNote,
                previousContent,
                noteFileNameFormat
              );
              if (renameTarget) {
                await renameItem(previousNote, renameTarget);
                emitTreeInvalidated();
              }
            }
          }
        } catch (error) {
          console.error("[notes] failed to flush previous note", error);
        }
      }

      if (!activeNote) {
        if (!cancelled) {
          setNoteDirty(false);
        }
        return;
      }

      const content = await readNote(activeNote);
      if (!cancelled) {
        setNoteContent(content);
        setNoteDirty(false);
        setSaveError(null);
        noteContentRef.current = content;
      }
    };

    void run();

    return () => {
      cancelled = true;
    };
  }, [activeNote, noteFileNameFormat, saveNow]);

  // Autosave with debounce
  useEffect(() => {
    if (!activeNote || !noteDirty) {
      return;
    }
    if (saveTimer.current) {
      window.clearTimeout(saveTimer.current);
    }
    saveTimer.current = window.setTimeout(() => {
      void saveNow(activeNote, noteContent);
    }, 400);
    return () => {
      if (saveTimer.current) {
        window.clearTimeout(saveTimer.current);
      }
    };
  }, [activeNote, noteContent, noteDirty, saveNow]);

  const handleEditorChange = useCallback(
    (markdown: string) => {
      if (!activeNote) {
        setDraftNoteContent((prev) => (prev === markdown ? prev : markdown));
        return;
      }
      setNoteContent((prev) => (prev === markdown ? prev : markdown));
      noteContentRef.current = markdown;
      setNoteDirty(true);
      noteDirtyRef.current = true;
      setSaveError(null);
    },
    [activeNote]
  );

  const clearNote = useCallback(() => {
    setNoteContent("");
    setNoteDirty(false);
    noteDirtyRef.current = false;
  }, []);

  const clearDraft = useCallback(() => {
    setDraftNoteContent("");
  }, []);

  const primeNoteContent = useCallback((markdown: string) => {
    setNoteContent(markdown);
    noteContentRef.current = markdown;
    setNoteDirty(false);
    noteDirtyRef.current = false;
    setSaveError(null);
  }, []);

  const flushSave = useCallback(async () => {
    if (saveTimer.current) {
      window.clearTimeout(saveTimer.current);
      saveTimer.current = null;
    }
    if (!activeNoteRef.current || !noteDirtyRef.current) {
      return;
    }
    await saveNow(activeNoteRef.current, noteContentRef.current);
  }, [saveNow]);

  const retrySave = useCallback(async () => {
    if (!activeNoteRef.current) {
      return;
    }
    await saveNow(activeNoteRef.current, noteContentRef.current);
  }, [saveNow]);

  useEffect(() => {
    return () => {
      if (saveTimer.current) {
        window.clearTimeout(saveTimer.current);
      }
    };
  }, []);

  const isSaved = !noteDirty && !isSaving && !saveError;

  return {
    noteContent,
    draftNoteContent,
    noteDirty,
    isSaving,
    saveError,
    isSaved,
    handleEditorChange,
    clearNote,
    clearDraft,
    primeNoteContent,
    flushSave,
    retrySave,
  };
}
import {
  createContext,
  useContext,
  useEffect,
  useRef,
  type ReactNode,
} from "react";
import { useNoteEditor } from "./use-note-editor";
import { useSelection } from "@/app/state/selection-store";
import { useProfiles } from "@/features/profiles/hooks/profiles-context";

type EditorContextValue = {
  noteContent: string;
  draftNoteContent: string;
  isNoteSaving: boolean;
  noteSaveError: string | null;
  handleEditorChange: (markdown: string) => void;
  clearNote: () => void;
  clearDraft: () => void;
  primeNoteContent: (markdown: string) => void;
  flushSave: () => Promise<void>;
  retrySave: () => Promise<void>;
  rightPaneRef: React.RefObject<HTMLDivElement | null>;
};

const EditorContext = createContext<EditorContextValue | null>(null);

export function EditorProvider({
  children,
}: {
  children: ReactNode;
}) {
  const { activeProfileId, activeProfileNotesRoot, syncSettings } = useProfiles();
  const activeNote = useSelection((state) => state.activeNote);

  const {
    noteContent,
    draftNoteContent,
    isSaving: isNoteSaving,
    saveError: noteSaveError,
    handleEditorChange,
    clearNote,
    clearDraft,
    primeNoteContent,
    flushSave,
    retrySave,
  } = useNoteEditor(activeNote, syncSettings.noteFileNameFormat);

  const rightPaneRef = useRef<HTMLDivElement | null>(null);

  // Clear editor state when profile identity or notes root changes
  useEffect(() => {
    if (activeProfileId) {
      clearNote();
      clearDraft();
    }
  }, [activeProfileId, activeProfileNotesRoot, clearNote, clearDraft]);

  return (
    <EditorContext.Provider
      value={{
        noteContent,
        draftNoteContent,
        isNoteSaving,
        noteSaveError,
        handleEditorChange,
        clearNote,
        clearDraft,
        primeNoteContent,
        flushSave,
        retrySave,
        rightPaneRef,
      }}
    >
      {children}
    </EditorContext.Provider>
  );
}

export function useEditor() {
  const context = useContext(EditorContext);
  if (!context) {
    throw new Error("useEditor must be used within an EditorProvider");
  }
  return context;
}
