import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useShallow } from "zustand/react/shallow";

import { useSelection } from "@/app/state/selection-store";
import { APP_EXTENSIONS } from "@/features/extensions/registry";
import { writeNote } from "@/features/notes/api/notes-api";
import { useEditor } from "@/features/notes/editor/hooks/editor-context";
import type { LensNote } from "@/features/lens/hooks/use-lens-annotations";
import { getLatestFeedTargetTimestamp } from "@/features/notes/navigation/model/feed-tree-model";
import { useNotesTree } from "@/features/notes/navigation/state/notes-tree-context";
import { FEED_FOLDER_PATH } from "@typenotes/shared/constants";
import { sanitizeRecordingEditorContent } from "@typenotes/shared/format";

export function useDesktopEditorPane() {
  const { activeFolder, activeNote, selectedNotes } = useSelection(
    useShallow((state) => ({
      activeFolder: state.activeFolder,
      activeNote: state.activeNote,
      selectedNotes: state.selectedNotes,
    }))
  );
  const [isLensPinned, setIsLensPinned] = useState(false);
  const [isLensMenuOpen, setIsLensMenuOpen] = useState(false);
  const {
    noteContent,
    draftNoteContent,
    handleEditorChange: updateEditorContent,
    flushSave,
    primeNoteContent,
    rightPaneRef,
  } = useEditor();
  const {
    notes,
    notePreviews,
    allNotePreviews,
    activeFeedNode,
    createNewNote,
  } = useNotesTree();
  const draftCreationRef = useRef<Promise<string | null> | null>(null);
  const pendingDraftRef = useRef("");

  const handleEditorChange = useCallback(
    (nextMarkdown: string) => {
      updateEditorContent(nextMarkdown);
      if (activeNote) {
        return;
      }

      pendingDraftRef.current = nextMarkdown;
      if (!nextMarkdown.trim() || draftCreationRef.current) {
        return;
      }

      const folderPath = activeFolder || FEED_FOLDER_PATH;
      const targetTimestampMs =
        folderPath === FEED_FOLDER_PATH
          ? getLatestFeedTargetTimestamp(activeFeedNode) ?? undefined
          : undefined;
      const initialContent = nextMarkdown;
      const creation = createNewNote(
        folderPath,
        initialContent,
        targetTimestampMs
      )
        .then(async (path) => {
          if (!path) {
            return null;
          }
          const latestContent = pendingDraftRef.current;
          if (latestContent !== initialContent) {
            await writeNote(path, latestContent);
            primeNoteContent(latestContent);
            window.dispatchEvent(new CustomEvent("note-previews-invalidated"));
          }
          return path;
        })
        .catch((error) => {
          console.error("[notes] failed to create note from editor draft", error);
          return null;
        })
        .finally(() => {
          draftCreationRef.current = null;
        });
      draftCreationRef.current = creation;
    },
    [
      activeFeedNode,
      activeFolder,
      activeNote,
      createNewNote,
      primeNoteContent,
      updateEditorContent,
    ]
  );

  const selectedNotePaths = useMemo(() => {
    const orderedByMiddleList = notes
      .map((note) => note.path)
      .filter((path) => selectedNotes.has(path));
    const remainingSelected = Array.from(selectedNotes).filter(
      (path) => !orderedByMiddleList.includes(path)
    );
    const mergedSelection = [...orderedByMiddleList, ...remainingSelected];
    if (mergedSelection.length > 0) {
      return mergedSelection;
    }
    return activeNote ? [activeNote] : [];
  }, [activeNote, notes, selectedNotes]);

  useEffect(() => {
    if (APP_EXTENSIONS.multiLens && selectedNotes.size > 1) {
      setIsLensPinned(true);
    }
  }, [selectedNotes]);

  const canOpenLens = APP_EXTENSIONS.multiLens && selectedNotePaths.length > 0;
  const shouldShowLens =
    APP_EXTENSIONS.multiLens && (selectedNotePaths.length > 1 || isLensPinned);

  // Only the lazy lens component needs this shape; keeping the derivation here
  // prevents the right pane from knowing about preview fallback details.
  const lensNotes = useMemo<LensNote[]>(
    () =>
      selectedNotePaths.map((path) => {
        const preview = notePreviews[path] || allNotePreviews[path];
        return {
          path,
          title: preview?.title || path.split("/").pop()?.replace(/\.md$/i, "") || path,
          dateLabel: preview?.dateLabel || "",
          isRecording: Boolean(preview?.isRecording),
          transcriptionStatus: preview?.transcriptionStatus || null,
        };
      }),
    [allNotePreviews, notePreviews, selectedNotePaths]
  );

  const activeNotePreview = activeNote
    ? notePreviews[activeNote] || allNotePreviews[activeNote]
    : undefined;
  const editorMarkdown =
    activeNote && activeNotePreview?.isRecording
      ? sanitizeRecordingEditorContent(noteContent, activeNotePreview.transcriptionStatus)
      : activeNote
        ? noteContent
        : draftNoteContent;

  const openLens = useCallback(() => {
    if (!APP_EXTENSIONS.multiLens) {
      return;
    }
    setIsLensPinned(true);
    setIsLensMenuOpen(false);
  }, []);

  const closeLens = useCallback(() => {
    setIsLensPinned(false);
  }, []);

  const syncActiveNoteContent = useCallback(
    (nextMarkdown: string) => {
      if (activeNote) {
        handleEditorChange(nextMarkdown);
      }
    },
    [activeNote, handleEditorChange]
  );

  return {
    activeNote,
    selectedNotePaths,
    activeNotePreview,
    editorMarkdown,
    handleEditorChange,
    flushSave,
    rightPaneRef,
    canOpenLens,
    shouldShowLens,
    lensNotes,
    isLensMenuOpen,
    setIsLensMenuOpen,
    openLens,
    closeLens,
    syncActiveNoteContent,
  };
}
  return direction < 0 ? 1 : view.state.doc.content.size;
};

const toolbarButton =
  "rounded-md border border-transparent px-2 py-1 text-xs font-medium text-[var(--ui-muted)] transition-colors hover:border-[var(--ui-border)] hover:bg-[var(--ui-select)] hover:text-[var(--ui-text)]";

const splitEditorMarkdown = (markdown: string) => {
  const split = splitFrontmatter(markdown);
  const lensSplit = splitLensBackmatterBlock(split.body);
  return {
    frontmatterBlock: split.frontmatterBlock,
    backmatterBlock: lensSplit.rawBlock,
    body: stripInlineAnnotationMetadata(lensSplit.content),
  };
};

export function NoteEditor({ markdown, onChange }: NoteEditorProps) {
  const showVimModeIndicator = useAppearance(
    (state) => state.showVimModeIndicator
  );
  const [vimMode, setVimModeState] = useState<VimMode>("normal");
  const [vimCursorRect, setVimCursorRect] = useState<VimCursorRect | null>(null);
  const vimModeRef = useRef<VimMode>("normal");
  const visualAnchorRef = useRef<number | null>(null);
  const verticalGoalLeftRef = useRef<number | null>(null);
  const isVerticalMotionRef = useRef(false);
  const isSyncing = useRef(false);
  const latestMarkdown = useRef(markdown);
  const scrollRef = useRef<HTMLDivElement | null>(null);
  const initialContentRef = useRef(splitEditorMarkdown(markdown));
  const frontmatterRef = useRef<string | null>(initialContentRef.current.frontmatterBlock);
  const backmatterRef = useRef<string | null>(initialContentRef.current.backmatterBlock);

  const setVimMode = useCallback((mode: VimMode) => {
    vimModeRef.current = mode;
    visualAnchorRef.current = null;
    setVimModeState(mode);
  }, []);

  const updateVimCursor = useCallback((view: EditorView) => {
    const scrollElement = scrollRef.current;
    if (!scrollElement || !view.hasFocus()) {
      setVimCursorRect(null);
      return;
    }
    try {
      const position = view.state.selection.head;
      const coords = view.coordsAtPos(position, 1);
      const nextPosition = Math.min(view.state.doc.content.size, position + 1);
      const nextCoords = view.coordsAtPos(nextPosition, -1);
      const computedStyle = window.getComputedStyle(view.dom);
      const fontSize = Number.parseFloat(computedStyle.fontSize) || 16;
      const measuredWidth =
        Math.abs(nextCoords.top - coords.top) < 2
          ? nextCoords.left - coords.left
          : 0;
      const scrollRect = scrollElement.getBoundingClientRect();
      const nextRect = {
        left: coords.left - scrollRect.left + scrollElement.scrollLeft,
        top: coords.top - scrollRect.top + scrollElement.scrollTop,
        width: Math.max(7, Math.min(fontSize * 1.2, measuredWidth || fontSize * 0.62)),
        height: Math.max(14, coords.bottom - coords.top),
      };
      setVimCursorRect((current) =>
        current &&
        Math.abs(current.left - nextRect.left) < 0.5 &&
        Math.abs(current.top - nextRect.top) < 0.5 &&
        Math.abs(current.width - nextRect.width) < 0.5 &&
        Math.abs(current.height - nextRect.height) < 0.5
          ? current
          : nextRect
      );
    } catch {
      setVimCursorRect(null);
    }
  }, []);

  const moveVimSelection = useCallback(
    (view: EditorView, targetPosition: number) => {
      const target = clampDocumentPosition(view, targetPosition);
      const normalizedHead = TextSelection.near(
        view.state.doc.resolve(target)
      ).head;
      const selection =
        vimModeRef.current === "visual"
          ? TextSelection.create(
              view.state.doc,
              visualAnchorRef.current ?? view.state.selection.anchor,
              normalizedHead
            )
          : TextSelection.near(view.state.doc.resolve(normalizedHead));
      view.dispatch(view.state.tr.setSelection(selection).scrollIntoView());
    },
    []
  );

  const handleVimKeyDown = useCallback(
    (view: EditorView, event: KeyboardEvent) => {
      const mode = vimModeRef.current;
      if (event.key === "Escape") {
        event.preventDefault();
        event.stopPropagation();
        const head = view.state.selection.head;
        verticalGoalLeftRef.current = null;
        setVimMode("normal");
        moveVimSelection(view, head);
        return true;
      }
      if (mode === "insert") {
        return false;
      }
      if (event.metaKey || event.altKey) {
        return false;
      }

      const key = event.key.toLowerCase();
      const direction = key === "j" ? 1 : key === "k" ? -1 : null;
      if (direction) {
        event.preventDefault();
        event.stopPropagation();
        const lineCount = event.ctrlKey ? VIM_JUMP_LINES : 1;
        const currentCoords = view.coordsAtPos(view.state.selection.head, 1);
        const goalLeft =
          verticalGoalLeftRef.current ?? currentCoords.left + 1;
        verticalGoalLeftRef.current = goalLeft;
        isVerticalMotionRef.current = true;
        moveVimSelection(
          view,
          getVerticalPosition(
            view,
            view.state.selection.head,
            direction,
            lineCount,
            goalLeft
          )
        );
        isVerticalMotionRef.current = false;
        return true;
      }
      if (event.ctrlKey) {
        return false;
      }
      if (key === "h" || key === "l") {
        event.preventDefault();
        event.stopPropagation();
        verticalGoalLeftRef.current = null;
        moveVimSelection(
          view,
          view.state.selection.head + (key === "h" ? -1 : 1)
        );
        return true;
      }
      if (key === "v") {
        event.preventDefault();
        event.stopPropagation();
        verticalGoalLeftRef.current = null;
        if (mode === "visual") {
          const head = view.state.selection.head;
          setVimMode("normal");
          moveVimSelection(view, head);
        } else {
          visualAnchorRef.current = view.state.selection.head;
          vimModeRef.current = "visual";
          setVimModeState("visual");
        }
        return true;
      }
      if (key === "i" || key === "a") {
        event.preventDefault();
        event.stopPropagation();
        verticalGoalLeftRef.current = null;
        if (key === "a") {
          moveVimSelection(view, view.state.selection.head + 1);
        }
        setVimMode("insert");
        return true;
      }

