      // destructive editing until the user explicitly enters Insert mode.
      if (
        event.key.length === 1 ||
        event.key === "Enter" ||
        event.key === "Backspace" ||
        event.key === "Delete"
      ) {
        event.preventDefault();
        event.stopPropagation();
        return true;
      }
      return false;
    },
    [moveVimSelection, setVimMode]
