        if (!cancelled) {
          setNoteDirty(false);
        }
        return;
      }

      const content = await readNote(activeNote);
      if (!cancelled) {
        setNoteContent(content);
        setLoadedNotePath(activeNote);
        setNoteDirty(false);
        setSaveError(null);
        noteContentRef.current = content;
      }
    };

    void run();

    return () => {
      cancelled = true;
