      .map((note) => note.path)
      .filter((path) => selectedNotes.has(path));
    const remainingSelected = Array.from(selectedNotes).filter(
      (path) => !orderedByMiddleList.includes(path)
    );
    const mergedSelection = [...orderedByMiddleList, ...remainingSelected];
    if (mergedSelection.length > 0) {
      return mergedSelection;
    }
    return activeNote ? [activeNote] : [];
  }, [activeNote, notes, selectedNotes]);

  useEffect(() => {
    if (APP_EXTENSIONS.multiLens && selectedNotes.size > 1) {
      setIsLensPinned(true);
    }
  }, [selectedNotes]);

  const canOpenLens = APP_EXTENSIONS.multiLens && selectedNotePaths.length > 0;
  const shouldShowLens =
    APP_EXTENSIONS.multiLens && (selectedNotePaths.length > 1 || isLensPinned);

  // Only the lazy lens component needs this shape; keeping the derivation here
  // prevents the right pane from knowing about preview fallback details.
  const lensNotes = useMemo<LensNote[]>(
    () =>
      selectedNotePaths.map((path) => {
        const preview = notePreviews[path] || allNotePreviews[path];
        return {
          path,
          title: preview?.title || path.split("/").pop()?.replace(/\.md$/i, "") || path,
          dateLabel: preview?.dateLabel || "",
          isRecording: Boolean(preview?.isRecording),
          transcriptionStatus: preview?.transcriptionStatus || null,
        };
      }),
    [allNotePreviews, notePreviews, selectedNotePaths]
  );

  const activeNotePreview = activeNote
    ? notePreviews[activeNote] || allNotePreviews[activeNote]
    : undefined;
  const editorMarkdown =
    activeNote && activeNotePreview?.isRecording
      ? sanitizeRecordingEditorContent(noteContent, activeNotePreview.transcriptionStatus)
      : activeNote
        ? noteContent
        : draftNoteContent;

  const openLens = useCallback(() => {
    if (!APP_EXTENSIONS.multiLens) {
      return;
    }
    setIsLensPinned(true);
    setIsLensMenuOpen(false);
  }, []);

  const closeLens = useCallback(() => {
    setIsLensPinned(false);
  }, []);

  const syncActiveNoteContent = useCallback(
    (nextMarkdown: string) => {
      if (activeNote) {
        handleEditorChange(nextMarkdown);
      }
    },
    },
    onUpdate: ({ editor: currentEditor }) => {
      if (isSyncing.current) {
        return;
      }
      const nextBodyMarkdown = htmlToMarkdown(currentEditor.getHTML());
      const frontmatterJoined = joinFrontmatter(frontmatterRef.current, nextBodyMarkdown);
      const nextMarkdown = appendRawLensBackmatterBlock(
        frontmatterJoined,
        backmatterRef.current
      );
      latestMarkdown.current = nextMarkdown;
      onChange(nextMarkdown);
      requestAnimationFrame(() => keepCaretBreathingRoom(currentEditor));
    },
  });

  useEffect(() => {
    if (!editor) {
      return;
    }
    if (markdown === latestMarkdown.current) {
      return;
    }
    const incoming = splitEditorMarkdown(markdown);
    frontmatterRef.current = incoming.frontmatterBlock;
    backmatterRef.current = incoming.backmatterBlock;
    const currentBodyMarkdown = htmlToMarkdown(editor.getHTML());
    if (currentBodyMarkdown === incoming.body) {
      latestMarkdown.current = markdown;
      return;
    }
    isSyncing.current = true;
    editor.commands.setContent(markdownToHtml(incoming.body), { emitUpdate: false });
    isSyncing.current = false;
    latestMarkdown.current = markdown;
  }, [editor, markdown]);

  useEffect(() => {
    if (!editor || !documentKey || documentKey === lastDocumentKeyRef.current) {
      return;
    }
    lastDocumentKeyRef.current = documentKey;

    // Promoting a focused draft to a persisted note is not navigation: keep
    // the insertion point so background note creation never interrupts typing.
    if (editor.view.hasFocus() && vimModeRef.current === "insert") {
      return;
    }

    verticalGoalLeftRef.current = null;
    setVimMode("normal");
    editor.view.dispatch(
      editor.view.state.tr
        .setSelection(TextSelection.atStart(editor.view.state.doc))
        .scrollIntoView()
    );
    if (scrollRef.current) {
      scrollRef.current.scrollTop = 0;
      scrollRef.current.scrollLeft = 0;
    }
    requestAnimationFrame(() => updateVimCursor(editor.view));
  }, [documentKey, editor, setVimMode, updateVimCursor]);

  useEffect(() => {
    if (!editor || !scrollRef.current) {
      return;
    }
    const observer = new ResizeObserver(() => updateVimCursor(editor.view));
    observer.observe(scrollRef.current);
    return () => observer.disconnect();
  }, [editor, updateVimCursor]);

  if (!editor) {
    return (
      <div className="flex h-full items-center justify-center text-sm text-[var(--ui-muted)]">
        Loading editor...
      </div>
    );
  }

  return (
    <div className="tiptap-editor" data-vim-mode={vimMode}>
      <div className="tiptap-toolbar">
        <button
          type="button"

        ? noteContent
        : draftNoteContent;

  const openLens = useCallback(() => {
    if (!APP_EXTENSIONS.multiLens) {
      return;
    }
    setIsLensPinned(true);
    setIsLensMenuOpen(false);
  }, []);

  const closeLens = useCallback(() => {
    setIsLensPinned(false);
  }, []);

  const syncActiveNoteContent = useCallback(
    (nextMarkdown: string) => {
      if (activeNote) {
        handleEditorChange(nextMarkdown);
      }
    },
    [activeNote, handleEditorChange]
  );

  return {
    activeNote,
    loadedNotePath,
    selectedNotePaths,
    activeNotePreview,
    editorMarkdown,
    handleEditorChange,
    flushSave,
    rightPaneRef,
    canOpenLens,
    shouldShowLens,
    lensNotes,
    isLensMenuOpen,
    setIsLensMenuOpen,
    openLens,
    closeLens,
    syncActiveNoteContent,
  };
}

